import unittest

from policy import publish_enabled
from service import publication_state


class PolicyTests(unittest.TestCase):
    def test_absent_setting_uses_declared_default(self):
        self.assertFalse(publish_enabled({}))
        self.assertEqual(publication_state({}), "disabled")

    def test_explicit_true_still_enables(self):
        self.assertTrue(publish_enabled({"publish_enabled": True}))
        self.assertEqual(publication_state({"publish_enabled": True}), "enabled")


if __name__ == "__main__":
    unittest.main()
